from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.vision.imageanalysis.models import VisualFeatures
from azure.core.credentials import AzureKeyCredential


def describe_image(payload, config=None):
    config = config or {}
    with ImageAnalysisClient(config['endpoint'], AzureKeyCredential(config['api_key'])) as client:
        result = client.analyze(image_data=payload['image_bytes'], visual_features=[VisualFeatures.CAPTION])
    caption = result.caption.content
    return {'description': caption}

import boto3


def detect_image_text(payload, config=None):
    textract = boto3.client('textract', region_name=config['region'], aws_access_key_id=config['aws_access_key_id'], aws_secret_access_key=config['aws_secret_access_key'])
    response = textract.detect_document_text(Document={'Bytes': payload['image_bytes']})
    text = ' '.join([item['Text'] for item in response['Blocks'] if item['BlockType'] == 'LINE'])
    return {'text': text}

import os


def get_vision_client(config):
    return ImageAnalysisClient(config['endpoint'], AzureKeyCredential(config['api_key']))

from azure.ai.vision.imageanalysis.models import VisualFeatures


def normalize_labels(result):
    return [{'name': tag.name, 'confidence': tag.confidence} for tag in result.tags.list]


def normalize_description(result):
    return result.caption.content


def normalize_text(response):
    return ' '.join([item['Text'] for item in response['Blocks'] if item['BlockType'] == 'LINE'])


def normalize_safety(response):
    return {'adult': response.safe_search_annotation.adult, 'spoof': response.safe_search_annotation.spoof, 'medical': response.safe_search_annotation.medical, 'violence': response.safe_search_annotation.violence}

from google.cloud import translate_v2 as translate


def alt_text_translate(payload, config=None):
    client = translate.Client()
    translation = client.translate(payload['description'], target_language=config['target_language'])
    return {'translated_description': translation['translatedText']}

import re


def visual_safety_text(payload, config=None):
    unsafe_patterns = [re.compile(pattern) for pattern in config['unsafe_patterns']]
    for pattern in unsafe_patterns:
        if pattern.search(payload['text']):
            return {'unsafe': True}
    return {'unsafe': False}

import boto3


def image_asset_archive(payload, config=None):
    s3 = boto3.client('s3', region_name=config['region'], aws_access_key_id=config['aws_access_key_id'], aws_secret_access_key=config['aws_secret_access_key'])
    s3.put_object(Bucket=config['bucket_name'], Key=payload['image_name'], Body=payload['image_bytes'])
    return {'archived': True}
